/// `kbdnec95.dll` export `KbdLayerDescriptor`: the layout's tables. The name is per layout so that
/// every layout can live in one staticlib; its .spec maps it onto the real name.
#[export_name = "kbdnec95_KbdLayerDescriptor"]
pub unsafe extern "system" fn KbdLayerDescriptor() -> PKBDTABLES {
    addr_of_mut!(keyboard_layout_table.Base) as PKBDTABLES
}

/// `kbdnec95.dll` export `KbdNlsLayerDescriptor`: its NLS tables. The name is per layout so that
/// every layout can live in one staticlib; its .spec maps it onto the real name.
#[export_name = "kbdnec95_KbdNlsLayerDescriptor"]
pub unsafe extern "system" fn KbdNlsLayerDescriptor() -> PKBDNLSTABLES {
    addr_of_mut!(nls_layer) as PKBDNLSTABLES
}
